my $repo = "/bench/repo";
open my $df, "<", "/tmp/internal_defs.txt" or die;
my @defs;
while (<$df>) {
  chomp;
  my ($qual, $name, $recv, $file) = split /\t/, $_;
  push @defs, {qual=>$qual, name=>$name, recv=>$recv||"", file=>$file};
}

my @all = map { chomp; $_ } split /\n/, `find /bench/repo -name "*.go" ! -name "*_test.go"`;
my %contents;
for my $f (@all) {
  open my $fh, "<", $f or next;
  $contents{$f} = do { local $/; <$fh> };
  close $fh;
}

sub count_for {
  my ($d) = @_;
  my $name = $d->{name};
  my $cnt = 0;
  for my $f (@all) {
    my $c = $contents{$f};
    while ($c =~ /\.$name\s*\(/g) { $cnt++ }
    if ($d->{recv} eq "") {
      while ($c =~ /\b$name\s*\(/g) { $cnt++ }
    }
  }
  # subtract declaration lines
  my $defpath = "$repo/$d->{file}";
  if (open my $fh, "<", $defpath) {
    while (<$fh>) {
      $cnt-- if /^func\s+/ && /\b$name\s*\(/;
    }
  }
  return $cnt > 0 ? $cnt : 0;
}

my @res;
for my $d (@defs) {
  my $c = count_for($d);
  push @res, [$c, $d->{qual}, $d->{file}] if $c >= 3;
}
@res = sort { $b->[0] <=> $a->[0] || $a->[2] cmp $b->[2] } @res;
for (@res[0..39]) {
  printf "%4d  %s  —  %s\n", @$_;
}
' 2>&1

