my $repo = "/bench/repo";
open my $df, "<", "/tmp/internal_defs.txt" or die;
my @defs;
while (<$df>) {
  chomp;
  my ($qual, $name, $recv, $file) = split /\t/, $_;
  push @defs, {qual=>$qual, name=>$name, recv=>$recv||"", file=>$file};
}

open my $af, "-|", "find", $repo, "-name", "*.go", "!", "-name", "*_test.go" or die;
chomp(my @all = <$af>);
close $af;

my %contents;
for my $f (@all) {
  open my $fh, "<", $f or next;
  $contents{$f} = do { local $/; <$fh> };
  close $fh;
}

sub count_for {
  my ($d) = @_;
  my $name = $d->{name};
  my $cnt = 0;
  for my $f (@all) {
    my $c = $contents{$f};
    while ($c =~ /\.$name\s*\(/g) { $cnt++ }
    if ($d->{recv} eq "") {
      while ($c =~ /\b\Q$name\E\s*\(/g) { $cnt++ }
    }
  }
  my $defpath = "$repo/$d->{file}";
  if (open my $fh, "<", $defpath) {
    while (<$fh>) {
      $cnt-- if /^func\s+/ && /\b\Q$name\E\s*\(/;
    }
  }
  return $cnt > 0 ? $cnt : 0;
}

my @res;
for my $d (@defs) {
  my $c = count_for($d);
  push @res, [$c, $d->{qual}, $d->{file}] if $c >= 1;
}
@res = sort { $b->[0] <=> $a->[0] || $a->[2] cmp $b->[2] } @res;
for (0..49) {
  last unless $res[$_];
  printf "%4d  %s  —  %s\n", @{$res[$_]};
}

